#include "routing_search.hpp"
#include <iostream>
int main(){Graph g;std::array<int,120*550>map;map.fill(-1);for(Node s=0;s<g.sites();++s){auto a=archdata::SITES[s];map[a.x*550+a.y]=s;}uint64_t checked=0,missing=0,cost_mismatch=0,destination_mismatch=0;for(Node s=0;s<g.sites();++s){auto a=archdata::SITES[s];if(a.y<50||a.y>199)continue;for(unsigned v=0;v<archdata::K;++v){auto m=g.forward_vector_move(s,v);if(m.site==NONE)continue;auto b=archdata::SITES[m.site];if(b.y<50||b.y>199)continue;for(int shift:{100,200,300}){++checked;int t=map[a.x*550+a.y+shift];if(t<0){++missing;continue;}auto z=g.forward_vector_move(t,v);if(z.site==NONE){++missing;continue;}auto c=archdata::SITES[z.site];if(c.x!=b.x||c.y!=b.y+shift)++destination_mismatch;if(z.delay!=m.delay)++cost_mismatch;}}}std::cout<<"{\"translated_edges\":"<<checked<<",\"missing\":"<<missing<<",\"cost_mismatch\":"<<cost_mismatch<<",\"destination_mismatch\":"<<destination_mismatch<<"}\n";return missing||cost_mismatch||destination_mismatch?1:0;}
